std::vector<NimLspTextEdit> NimLspFormat(const std::vector<std::string> &lines, int width, std::string *error) {
    std::vector<NimLspTextEdit> edits;
    std::string text;
    for (size_t i = 0; i < lines.size(); i++) {
        if (i) text += '\n';
        text += lines[i];
    }
    nimfmt::Options o;
    if (width > 0) o.width = width;
    const nimfmt::Result r = nimfmt::Format(text, o);
    if (!r.ok) {
        *error = r.error_line > 0 ? "line " + std::to_string(r.error_line) + ": " + r.error : r.error;
        return edits;
    }
    if (r.text == text) return edits;
    // One edit replacing the whole document (nix_lsp.cpp narrows it to the changed lines).
    NimLspTextEdit e;
    e.range.end_line = static_cast<int>(lines.size()) - 1;
    e.range.end_col = static_cast<int>(lines.back().size());
    e.new_text = r.text;
    edits.push_back(e);
    return edits;
}
